// Valida e normaliza os dados enviados pelo formulário do site
const body = $input.first().json.body || {};

// Anti-spam: campo invisível no formulário. Gente de verdade não preenche.
if (body.website) {
  return [{ json: { ok: false, spam: true, erro: 'spam' } }];
}

const nome = String(body.nome || '').trim().slice(0, 120);
const email = String(body.email || '').trim().toLowerCase().slice(0, 160);
let digits = String(body.whatsapp || '').replace(/\D/g, '');
if (digits.length === 10 || digits.length === 11) digits = '55' + digits; // adiciona o DDI do Brasil

const erros = [];
if (nome.length < 2) erros.push('nome');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) erros.push('email');
if (!/^55\d{10,11}$/.test(digits)) erros.push('whatsapp');

if (erros.length) {
  return [{ json: { ok: false, erro: 'Campos inválidos: ' + erros.join(', ') } }];
}

return [{
  json: {
    ok: true,
    nome,
    email,
    whatsapp: String(body.whatsapp || '').trim(),
    telefoneDigitos: digits,
    pagina: String(body.pagina || '').slice(0, 300),
    recebidoEm: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
  },
}];

// =====================================================================
// CONFIGURAÇÃO: preencha antes de ativar o fluxo
// =====================================================================
const CONFIG = {
  chatwootUrl: 'https://chatwoot.catalystcore.cloud', // endereço do seu Chatwoot
  accountId: 1,            // número que aparece na URL do Chatwoot: /app/accounts/1/...
  inboxId: 0,              // ID da caixa de entrada do WhatsApp (Configurações > Caixas de entrada)
  apiToken: 'COLE_AQUI_O_TOKEN', // Perfil > Token de acesso (Access Token)
  avisoPara: '5511993439117',    // quem recebe o aviso de novo contato (DDI + DDD + número)
  enviarBoasVindas: true,        // manda mensagem automática para quem preencheu o formulário
};
// =====================================================================

const lead = $input.first().json;
if (!lead.ok) return [{ json: { ignorado: true, motivo: lead.erro } }];

const base = CONFIG.chatwootUrl.replace(/\/$/, '') + '/api/v1/accounts/' + CONFIG.accountId;
const api = (method, path, body) => this.helpers.httpRequest({
  method,
  url: base + path,
  headers: { api_access_token: CONFIG.apiToken },
  body,
  json: true,
});

// Encontra ou cria o contato e devolve { contato, conversaId }
async function abrirConversa({ nome, digitos, email }) {
  // 1. procura o contato pelo telefone
  const busca = await api('GET', '/contacts/search?q=' + encodeURIComponent(digitos));
  let contato = (busca.payload || []).find(c => String(c.phone_number || '').replace(/\D/g, '') === digitos);

  // 2. cria se não existir
  if (!contato) {
    const novo = { inbox_id: CONFIG.inboxId, name: nome, phone_number: '+' + digitos };
    if (email) novo.email = email;
    let r;
    try {
      r = await api('POST', '/contacts', novo);
    } catch (e) {
      delete novo.email; // e-mail já usado por outro contato: cria só com o telefone
      r = await api('POST', '/contacts', novo);
    }
    contato = r.payload.contact || r.payload;
  }

  // 3. garante o vínculo do contato com a caixa de WhatsApp
  const det = await api('GET', '/contacts/' + contato.id);
  const vinculos = (det.payload && det.payload.contact_inboxes) || [];
  let vinculo = vinculos.find(v => v.inbox && v.inbox.id === CONFIG.inboxId);
  if (!vinculo) {
    vinculo = await api('POST', '/contacts/' + contato.id + '/contact_inboxes', { inbox_id: CONFIG.inboxId, source_id: digitos });
  }

  // 4. reaproveita conversa aberta ou cria uma nova
  const convs = await api('GET', '/contacts/' + contato.id + '/conversations');
  let conversa = (convs.payload || []).find(c => c.inbox_id === CONFIG.inboxId && c.status !== 'resolved');
  if (!conversa) {
    conversa = await api('POST', '/conversations', {
      source_id: vinculo.source_id,
      inbox_id: CONFIG.inboxId,
      contact_id: contato.id,
      status: 'open',
    });
  }
  return { contato, conversaId: conversa.id };
}

const enviar = (conversaId, content, privado = false) =>
  api('POST', '/conversations/' + conversaId + '/messages', { content, message_type: 'outgoing', private: privado });

const resultado = { lead: null, aviso: null, erros: [] };
const primeiroNome = lead.nome.split(' ')[0];

const resumo =
  '🚀 *Novo contato pelo site*\n\n' +
  '*Nome:* ' + lead.nome + '\n' +
  '*E-mail:* ' + lead.email + '\n' +
  '*WhatsApp:* ' + lead.whatsapp + '\n' +
  '*Recebido em:* ' + lead.recebidoEm +
  (lead.pagina ? '\n*Página:* ' + lead.pagina : '');

// A) Conversa com quem preencheu: nota interna com os dados + boas-vindas
try {
  const { conversaId } = await abrirConversa({ nome: lead.nome, digitos: lead.telefoneDigitos, email: lead.email });
  await enviar(conversaId, resumo + '\n\nOrigem: formulário "Conte o que você precisa construir".', true);
  if (CONFIG.enviarBoasVindas) {
    await enviar(conversaId,
      'Olá, ' + primeiroNome + '! Aqui é da Catalyst Core. 👋\n\n' +
      'Recebemos seu contato pelo site. Para adiantar, conte em poucas palavras o que você precisa construir ' +
      '(sistema, app, site, agente de IA ou automação) e, se tiver, o prazo desejado.\n\n' +
      'Um especialista vai falar com você em até 24 horas.');
  }
  resultado.lead = { conversaId };
} catch (e) {
  resultado.erros.push('lead: ' + (e.message || e));
}

// B) Aviso para o número da equipe
const aviso = String(CONFIG.avisoPara).replace(/\D/g, '');
if (aviso && aviso !== lead.telefoneDigitos) {
  try {
    const { conversaId } = await abrirConversa({ nome: 'Equipe Catalyst Core', digitos: aviso });
    await enviar(conversaId, resumo + '\n\nResponda pelo Chatwoot ou no WhatsApp: https://wa.me/' + lead.telefoneDigitos);
    resultado.aviso = { conversaId };
  } catch (e) {
    resultado.erros.push('aviso: ' + (e.message || e));
  }
}

return [{ json: resultado }];
